#include <iostream>

template <typename NODETYPE>
class List;

template <typename NODETYPE>
class ListNode {
    friend class List<NODETYPE>;
public:
    explicit ListNode(const NODETYPE& info)
        : data(info), nextPtr(nullptr) {}
    NODETYPE getData() const { return data; }
private:
    NODETYPE data;
    ListNode<NODETYPE>* nextPtr;
};

template <typename NODETYPE>
class List {
public:
    List() : firstPtr(nullptr), lastPtr(nullptr) {}

    ~List() {
        if (!isEmpty()) {
            ListNode<NODETYPE>* currentPtr = firstPtr;
            while (currentPtr != nullptr) {
                ListNode<NODETYPE>* tempPtr = currentPtr;
                currentPtr = currentPtr->nextPtr;
                delete tempPtr;
            }
        }
    }

    void insertAtFront(const NODETYPE& value) {
        ListNode<NODETYPE>* newPtr = getNewNode(value);
        if (isEmpty()) {
            firstPtr = lastPtr = newPtr;
        } else {
            newPtr->nextPtr = firstPtr;
            firstPtr = newPtr;
        }
    }

    void insertAtBack(const NODETYPE& value) {
        ListNode<NODETYPE>* newPtr = getNewNode(value);
        if (isEmpty()) {
            firstPtr = lastPtr = newPtr;
        } else {
            lastPtr->nextPtr = newPtr;
            lastPtr = newPtr;
        }
    }

    bool removeFromFront(NODETYPE& value) {
        if (isEmpty()) return false;
        ListNode<NODETYPE>* tempPtr = firstPtr;
        if (firstPtr == lastPtr) {
            firstPtr = lastPtr = nullptr;
        } else {
            firstPtr = firstPtr->nextPtr;
        }
        value = tempPtr->data;
        delete tempPtr;
        return true;
    }

    bool removeFromBack(NODETYPE& value) {
        if (isEmpty()) return false;
        ListNode<NODETYPE>* tempPtr = lastPtr;
        if (firstPtr == lastPtr) {
            firstPtr = lastPtr = nullptr;
        } else {
            ListNode<NODETYPE>* currentPtr = firstPtr;
            while (currentPtr->nextPtr != lastPtr) {
                currentPtr = currentPtr->nextPtr;
            }
            lastPtr = currentPtr;
            currentPtr->nextPtr = nullptr;
        }
        value = tempPtr->data;
        delete tempPtr;
        return true;
    }

    bool isEmpty() const {
        return firstPtr == nullptr;
    }

    void print() const {
        if (isEmpty()) {
            std::cout << "The list is empty\n";
            return;
        }
        std::cout << "The list is: ";
        ListNode<NODETYPE>* currentPtr = firstPtr;
        while (currentPtr != nullptr) {
            std::cout << currentPtr->data << ' ';
            currentPtr = currentPtr->nextPtr;
        }
        std::cout << "\n";
    }

private:
    ListNode<NODETYPE>* firstPtr;
    ListNode<NODETYPE>* lastPtr;

    ListNode<NODETYPE>* getNewNode(const NODETYPE& value) {
        return new ListNode<NODETYPE>(value);
    }
};

int main() {
    List<int> intList;
    intList.insertAtFront(10);
    intList.insertAtFront(5);
    intList.insertAtBack(20);
    intList.print();

    int val;
    if (intList.removeFromFront(val)) {
        std::cout << val << " removed from front\n";
    }
    if (intList.removeFromBack(val)) {
        std::cout << val << " removed from back\n";
    }
    intList.print();
    return 0;
}
